from __future__ import annotations

from typing import Optional


class ZKSDKError(Exception):
    """Base exception for all ZKTeco SDK errors."""

    pass


class ZKConnectionError(ZKSDKError):
    """Raised when failing to connect to or communicate with the ZKTeco device."""

    def __init__(
        self, message: str, host: Optional[str] = None, port: Optional[int] = None
    ):
        super().__init__(message)
        self.host = host
        self.port = port


class ZKDeviceError(ZKSDKError):
    """Raised when the ZKTeco device responds with a protocol or command error."""

    def __init__(
        self, message: str, command: Optional[str] = None, code: Optional[int] = None
    ):
        super().__init__(message)
        self.command = command
        self.code = code


class ZKUserNotFoundError(ZKSDKError):
    """Raised when a specified user (uid or user_id) is not found on the device."""

    def __init__(self, user_identifier: str | int):
        super().__init__(f"User '{user_identifier}' was not found on the device.")
        self.user_identifier = user_identifier


class ZKTemplateError(ZKSDKError):
    """Raised when reading, writing, or enrolling biometric templates fails."""

    pass


class ZKDeviceLockedError(ZKSDKError):
    """Raised when an operation cannot be completed because the device is busy or locked."""

    pass


class ZKRuleViolationError(ZKSDKError):
    """Raised when an access attempt violates configured software access rules (time/area)."""

    def __init__(self, message: str, user_id: str, area_name: Optional[str] = None):
        super().__init__(message)
        self.user_id = user_id
        self.area_name = area_name
